#!/usr/bin/env node
/**
 * Bakes skills/*.md into a TypeScript module.
 *
 * Cloudflare Workers has no filesystem, so the bundled playbooks cannot be read
 * from disk at runtime. This runs before every build; the generated file is
 * committed so a fresh clone type-checks without running it first.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const skillsDir = path.join(root, "skills");
const outFile = path.join(root, "src", "generated", "skills.ts");

function parseFrontMatter(text) {
  const match = /^---\n([\s\S]*?)\n---\n?([\s\S]*)$/.exec(text);
  if (!match) return { meta: {}, body: text };
  const meta = {};
  for (const line of match[1].split("\n")) {
    const idx = line.indexOf(":");
    if (idx === -1) continue;
    meta[line.slice(0, idx).trim()] = line.slice(idx + 1).trim().replace(/^["']|["']$/g, "");
  }
  return { meta, body: match[2] };
}

const files = fs.existsSync(skillsDir) ? fs.readdirSync(skillsDir).filter((f) => f.endsWith(".md")).sort() : [];

const entries = files.map((file) => {
  const { meta, body } = parseFrontMatter(fs.readFileSync(path.join(skillsDir, file), "utf8"));
  const name = meta.name ?? path.basename(file, ".md");
  return {
    name,
    title: meta.title ?? name,
    description: meta.description ?? "",
    keywords: (meta.keywords ?? "").split(",").map((k) => k.trim()).filter(Boolean),
    content: body.trim(),
  };
});

const output = `// Generated by scripts/bundle-skills.mjs — do not edit by hand.
// Run \`npm run bundle:skills\` after changing anything in skills/.

export interface BundledSkill {
  name: string;
  title: string;
  description: string;
  keywords: string[];
  content: string;
}

export const BUNDLED_SKILLS: BundledSkill[] = ${JSON.stringify(entries, null, 2)};
`;

fs.mkdirSync(path.dirname(outFile), { recursive: true });
fs.writeFileSync(outFile, output);
console.log(`Bundled ${entries.length} skill(s) into src/generated/skills.ts`);
